import { onDocumentLoaded } from "../utils/onDocumentLoaded";
import { domain as domainRegex } from "../utils/regex";
import { refreshCurrentUser } from "../utils/request";
import { getUrlPrefix, setUrlPrefix } from "../utils/storage";
import { reloadContentScriptUrls } from "../utils/url";

const setStatus = (msg: string): void => {
  const status = document.getElementById("status");
  if (status != null) {
    status.textContent = msg;
    setTimeout(() => {
      status.textContent = "";
    }, 5000);
  }
};

// Saves options to chrome.storage
const saveOptions = (): void => {
  const urlPrefixInput = document.getElementById(
    "urlPrefix",
  ) as HTMLInputElement;
  let urlPrefix = urlPrefixInput.value;
  const urlPrefixMatch = domainRegex.exec(urlPrefix ?? "")?.[0];
  if (urlPrefixMatch == null) {
    setStatus("Invalid url. Please fix the url and try again.");
    return;
  }
  // strip trailing slashes
  urlPrefix = urlPrefix.replace(/\/+$/, "");
  setUrlPrefix(urlPrefix).then(() => {
    setStatus("Options saved.");
    reloadContentScriptUrls();
  });
};

// Restores options state using the preferences stored in chrome.storage
function restoreOptions(): void {
  getUrlPrefix().then((urlPrefix) => {
    const urlPrefixInput = document.getElementById(
      "urlPrefix",
    ) as HTMLInputElement;
    urlPrefixInput.value = urlPrefix ?? "";
  });
}

function setVal(val: string): void {
  const urlPrefixInput = document.getElementById(
    "urlPrefix",
  ) as HTMLInputElement;
  urlPrefixInput.value = val;
  saveOptions();
}

onDocumentLoaded(restoreOptions);
document.getElementById("save")?.addEventListener("click", saveOptions);
document
  .getElementById("prod")
  ?.addEventListener("click", () => setVal("https://app.brighthire.ai"));
document
  .getElementById("dev")
  ?.addEventListener("click", () => setVal("https://localhost:3000"));

document
  .getElementById("refresh-flags")
  ?.addEventListener("click", async () => {
    await refreshCurrentUser();
  });
